class Config {
  std::string name_;
  std::vector<int> ports_;
public:
  Config(std::string n, std::vector<int> p) : name_(std::move(n)), ports_(std::move(p)) {}
  const std::string& name() const { return name_; }          // const query, no mutation
  std::span<const int> ports() const { return ports_; }      // read-only borrow
  Config with_port(int p) const {                            // copy-with: new value
    std::vector<int> next = ports_;
    next.push_back(p);
    return Config(name_, std::move(next));
  }
};

std::atomic<std::shared_ptr<const Config>> current{
    std::make_shared<const Config>(Config{"api", {8080}})};

void publish(Config next) {                       // writer: build fully, then swap
  current.store(std::make_shared<const Config>(std::move(next)));
}
void serve() {
  auto snapshot = current.load();                 // reader: stable immutable version
  use(snapshot->ports());                         // no lock, no copy
}

